                .current_dir(root)
                .output(),
        );

        let plan_path = root.join("plan.json");
        std::fs::write(
            &plan_path,
            serde_json::json!({
                "schemaVersion": 1,
                "rustCrates": [],
                "npmPlatformPackages": [],
                "npmMainPackages": [],
                "releases": []
            })
            .to_string(),
        )
